          "code": "import pandas as pd
import numpy as np
import os
import tempfile

file_path = '${item}'
df = pd.read_csv(file_path)

issues = []
repairs = []

missing_cols = df.columns[df.isnull().any()].tolist()
if missing_cols:
    issues.append(f"Missing values in columns: {missing_cols}")

duplicate_rows = df.duplicated().sum()
if duplicate_rows > 0:
    issues.append(f"Found {duplicate_rows} duplicate rows")

numeric_cols = df.select_dtypes(include=[np.number]).columns
for col in numeric_cols:
    Q1 = df[col].quantile(0.25)
    Q3 = df[col].quantile(0.75)
    IQR = Q3 - Q1
    lower = Q1 - 1.5 * IQR
    upper = Q3 + 1.5 * IQR
    outliers = df[(df[col] < lower) | (df[col] > upper)]
    if not outliers.empty:
        issues.append(f"Outliers detected in column '{col}': {len(outliers)} rows")

for col in df.columns:
    if df[col].dtype == 'object':
        converted = pd.to_numeric(df[col], errors='coerce')
        if converted.isna().sum() > 0 and converted.notna().sum() > 0:
            issues.append(f"Mixed types in column '{col}': some values are strings, some are numbers")

repairs_made = []
for col in df.columns:
    if df[col].isnull().any():
        if df[col].dtype in ['float64', 'int64']:
            median_val = df[col].median()
            df[col].fillna(median_val, inplace=True)
            repairs_made.append(f"Filled missing values in '{col}' with median {median_val}")
        else:
            mode_val = df[col].mode()[0] if not df[col].mode().empty else 'unknown'
            df[col].fillna(mode_val, inplace=True)
            repairs_made.append(f"Filled missing values in '{col}' with mode '{mode_val}'")

df.drop_duplicates(inplace=True)
if duplicate_rows > 0:
    repairs_made.append(f"Removed {duplicate_rows} duplicate rows")

revalidation_issues = []
if df.isnull().any().any():
    revalidation_issues.append("Missing values still present after repair")
if df.duplicated().sum() > 0:
    revalidation_issues.append("Duplicates still present after repair")
revalidation_status = "pass" if not revalidation_issues else "fail: " + "; ".join(revalidation_issues)

stats = {}
for col in numeric_cols:
    stats[col] = {
        'sum': float(df[col].sum()),
        'mean': float(df[col].mean()),
        'min': float(df[col].min()),
        'max': float(df[col].max()),
        'count': int(df[col].count())
    }

env['file_name'] = os.path.basename(file_path)
env['issues'] = issues
env['repairs'] = repairs_made
env['revalidation'] = revalidation_status
env['stats'] = stats",
